# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MÜLK SURESİ (TEBÂREKE): KİMLİK BİLGİLERİ VE ANA KONULARI</text>\n  <rect x="25" y="45" width="280" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="165" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Genel Özellikleri</text>\n  <text x="40" y="95" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Mushaf Sırası:</tspan> 67. Sure</text>\n  <text x="40" y="119" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Cüz:</tspan> 29. Cüzün ilk suresi</text>\n  <text x="40" y="143" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Nüzul Yeri ve Ayet:</tspan> Mekkî — 30 Ayet</text>\n  <text x="40" y="167" font-size="12" fill="#1e3a8a">• <tspan font-weight="bold">Diğer İsimleri:</tspan> Tebâreke, el-Vâkıye</text>\n  <text x="50" y="185" font-size="11" fill="#1e3a8a">(Koruyan), el-Münciye (Kurtaran)</text>\n  <text x="40" y="212" font-size="11" font-weight="bold" fill="#1d4ed8">Kelime Anlamı: Mülk = Hükümranlık</text>\n\n  <rect x="325" y="45" width="350" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="500" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Mülk Suresinin Temel Mesajları</text>\n  <text x="340" y="95" font-size="12" fill="#14532d">• <tspan font-weight="bold">1-2. Ayetler:</tspan> Ölüm ve hayatın yaratılış gayesi,</text>\n  <text x="350" y="113" font-size="11" fill="#14532d">kimin daha güzel amel işleyeceğinin imtihanıdır.</text>\n  <text x="340" y="138" font-size="12" fill="#14532d">• <tspan font-weight="bold">3-5. Ayetler:</tspan> Yedi kat göğün kusursuz düzeni.</text>\n  <text x="340" y="163" font-size="12" fill="#14532d">• <tspan font-weight="bold">10. Ayet:</tspan> "Şayet kulak verseydik veya aklımızı</text>\n  <text x="350" y="181" font-size="11" fill="#14532d">kullansaydık çılgın ateşin halkından olmazdık."</text>\n  <text x="340" y="208" font-size="12" fill="#14532d">• <tspan font-weight="bold">15 &amp; 30. Ayetler:</tspan> Rızık arayışı ve su nimeti.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">NEBE SURESİ (AMME): KİMLİK BİLGİLERİ VE KEVNİ DELİLLER</text>\n  <rect x="25" y="45" width="280" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="165" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Genel Özellikleri</text>\n  <text x="40" y="95" font-size="12" fill="#78350f">• <tspan font-weight="bold">Mushaf Sırası:</tspan> 78. Sure</text>\n  <text x="40" y="119" font-size="12" fill="#78350f">• <tspan font-weight="bold">Cüz:</tspan> 30. Cüzün (Amme) ilk suresi</text>\n  <text x="40" y="143" font-size="12" fill="#78350f">• <tspan font-weight="bold">Nüzul Yeri ve Ayet:</tspan> Mekkî — 40 Ayet</text>\n  <text x="40" y="167" font-size="12" fill="#78350f">• <tspan font-weight="bold">Diğer Adı:</tspan> Amme Suresi</text>\n  <text x="40" y="191" font-size="12" fill="#78350f">• <tspan font-weight="bold">Ana Kavram:</tspan> en-Nebeü\'l-Azîm</text>\n  <text x="50" y="210" font-size="11" font-weight="bold" fill="#b45309">(Büyük Haber = Kıyamet ve Diriliş)</text>\n\n  <rect x="325" y="45" width="350" height="195" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="500" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Dirilişe İşaret Eden Kevni Ayetler (6-16)</text>\n  <text x="340" y="95" font-size="12" fill="#581c87">• Yeryüzünün döşek/beşik, dağların kazık kılınması</text>\n  <text x="340" y="119" font-size="12" fill="#581c87">• İnsanların çiftler hâlinde yaratılması ve uyku nimeti</text>\n  <text x="340" y="143" font-size="12" fill="#581c87">• Gece ve gündüzün nöbetleşe düzeni</text>\n  <text x="340" y="167" font-size="12" fill="#581c87">• Yedi sağlam gök ve parlak kandil (Güneş)</text>\n  <text x="340" y="191" font-size="12" fill="#581c87">• Yağmurla ölü toprağın diriltilmesi → <tspan font-weight="bold">Ahirette</tspan></text>\n  <text x="350" y="210" font-size="11" font-weight="bold" fill="#6b21a8">insanların da kabirlerinden öyle çıkarılacağı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MÜLK VE NEBE SURELERİNİN KARŞILAŞTIRMALI ÖZETİ</text>\n  <rect x="25" y="48" width="650" height="190" rx="10" fill="#ffffff" stroke="#94a3b8" stroke-width="2"/>\n  <!-- Tablo Baslik -->\n  <rect x="25" y="48" width="650" height="36" rx="8" fill="#1e293b"/>\n  <text x="130" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#ffffff">Özellik / Kriter</text>\n  <text x="355" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#93c5fd">MÜLK SURESİ (Tebâreke)</text>\n  <text x="565" y="71" text-anchor="middle" font-size="12" font-weight="bold" fill="#fde047">NEBE SURESİ (Amme)</text>\n  <!-- Satir 1 -->\n  <text x="130" y="106" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">Sure No / Cüz / Ayet</text>\n  <text x="355" y="106" text-anchor="middle" font-size="12" fill="#1e3a8a">67. Sure • 29. Cüz • 30 Ayet</text>\n  <text x="565" y="106" text-anchor="middle" font-size="12" fill="#78350f">78. Sure • 30. Cüz • 40 Ayet</text>\n  <line x1="40" y1="118" x2="660" y2="118" stroke="#e2e8f0" stroke-width="1.5"/>\n  <!-- Satir 2 -->\n  <text x="130" y="140" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">Nüzul Dönemi</text>\n  <text x="355" y="140" text-anchor="middle" font-size="12" fill="#1e3a8a">Mekke Dönemi (Mekkî)</text>\n  <text x="565" y="140" text-anchor="middle" font-size="12" fill="#78350f">Mekke Dönemi (Mekkî)</text>\n  <line x1="40" y1="152" x2="660" y2="152" stroke="#e2e8f0" stroke-width="1.5"/>\n  <!-- Satir 3 -->\n  <text x="130" y="174" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">Anahtar Kavramlar</text>\n  <text x="355" y="174" text-anchor="middle" font-size="11" fill="#1e3a8a">el-Mülk, Ahsenü Amel, Yedi Gök</text>\n  <text x="565" y="174" text-anchor="middle" font-size="11" fill="#78350f">en-Nebeü\'l-Azîm, Yevmü\'l-Fasl</text>\n  <line x1="40" y1="186" x2="660" y2="186" stroke="#e2e8f0" stroke-width="1.5"/>\n  <!-- Satir 4 -->\n  <text x="130" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#0f172a">Hayata Mesajı</text>\n  <text x="355" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">Aklı kullanmak ve güzel amel işlemek</text>\n  <text x="565" y="212" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">Diriliş gününe takva ile hazırlanmak</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
